/**
 * The shadcn registry of the md-gb elements, one JSON file per page under
 * /3.0/r/: registry.json, an item per component family, md-theme.json and
 * md-theme-m3.json. Generated by scripts/m3/shadcn.mjs (data file
 * _data/shadcn.cjs). See docs/about/shadcn.md.
 */

class Registry {
  data() {
    return {
      pagination: {data: 'shadcn', size: 1, alias: 'file'},
      permalink: (data) => `/3.0/r/${data.file.name}.json`,
      eleventyExcludeFromCollections: true,
    };
  }

  render(data) {
    return data.file.json;
  }
}

module.exports = Registry;
